//! End-to-end generation differential: JS-produced .par2 files vs the
//! pure-Rust pipeline (Par2Gen + GenDriver over SharedBackend<NativeBackend>,
//! the wiring the shipped --no-default-features binary uses).
//! Oracle: generated by `node bin/parpar.js -s512B -r3` on the fixture
//! inputs; files live under /tmp/e2e (regenerated by the test if missing).

use parpar::args::{MethodRef, SpecTerm, SpecUnit};
use parpar::generate::{GenOpts, Par2Gen, SysEnv};
use parpar::native_backend::NativeBackend;
use parpar::par2::SharedBackend;
use parpar::pipeline::GenDriver;

/// Path to the JS CLI entry point: `$PARPAR_JS` override, else repo-
/// relative (crates/parpar -> repo root bin/parpar.js).
fn js_cli() -> Option<std::path::PathBuf> {
    if let Ok(p) = std::env::var("PARPAR_JS") {
        let p = std::path::PathBuf::from(p);
        if p.exists() {
            return Some(p);
        }
    }
    // the JS CLI also needs the compiled addon - without it parpar.js
    // dies on MODULE_NOT_FOUND instead of behaving like the oracle, so
    // parity tests must skip rather than compare a crash trace
    // CARGO_MANIFEST_DIR = rust/crates/parpar -> repo root is ../../..
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..");
    let p = root.join("bin/parpar.js");
    let addon = root.join("build/Release/parpar_gf.node");
    (p.exists() && addon.exists()).then_some(p)
}

/// Run the oracle generator over `args`/`files` -> `out.par2`; tries
/// `node parpar.js` first, falls back to the freshly built `parpar`
/// binary under PARPAR_FORCE_FFI=1 (same C++ engine the JS addon loads).
/// Returns false when no oracle is runnable (test should skip).
fn oracle_gen(out: &std::path::Path, args: &[&str], files: &[&std::path::Path]) -> bool {
    if let Some(script) = js_cli() {
        let st = std::process::Command::new("node")
            .arg(&script)
            .arg("-o")
            .arg(out)
            .args(args)
            .args(files)
            .status();
        if let Ok(st) = st {
            if st.success() {
                return true;
            }
            // JS addon missing/misbuilt - try the FFI binary instead
        } else {
            return ffi_oracle_gen(out, args, files);
        }
    }
    ffi_oracle_gen(out, args, files)
}

fn ffi_oracle_gen(out: &std::path::Path, args: &[&str], files: &[&std::path::Path]) -> bool {
    let bin = std::env::var("PARPAR_FFI_BIN").unwrap_or_else(|_| {
        std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../target/release/parpar")
            .to_string_lossy()
            .into_owned()
    });
    std::process::Command::new(bin)
        .arg("-q")
        .arg("-o")
        .arg(out)
        .args(args)
        .args(files)
        .env("PARPAR_FORCE_FFI", "1")
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

#[test]
fn e2e_gen_matches_js() {
    // fixture inputs (identical to the JS oracle's)
    let dir = std::env::temp_dir().join("e2e_rust");
    let in_dir = dir.join("in");
    std::fs::create_dir_all(&in_dir).unwrap();
    std::fs::write(
        in_dir.join("a.bin"),
        vec![0u8; 0]
            .into_iter()
            .chain((0..=255u8).cycle().take(2048))
            .collect::<Vec<_>>(),
    )
    .unwrap();
    std::fs::write(in_dir.join("b.bin"), vec![b'x'; 1000]).unwrap();

    // JS oracle (generated once; regenerate deterministically)
    let js_dir = std::env::temp_dir().join("e2e");
    {
        // recreate inputs the JS runs used
        std::fs::create_dir_all(js_dir.join("in")).unwrap();
        std::fs::write(
            js_dir.join("in/a.bin"),
            (0..=255u8).cycle().take(2048).collect::<Vec<u8>>(),
        )
        .unwrap();
        std::fs::write(js_dir.join("in/b.bin"), vec![b'x'; 1000]).unwrap();
        let a = js_dir.join("in/a.bin");
        let b = js_dir.join("in/b.bin");
        // every compared base needs an oracle output - a stale cache from
        // an earlier checkout may hold only a subset, so check each one
        for (base, args) in [
            ("out", vec!["-s512B", "-r3"]),
            (
                "outc",
                vec!["-s64K", "-r3", "-m64K", "--min-chunk-size", "1K"],
            ),
        ] {
            if js_dir.join(format!("{}.par2", base)).exists() {
                continue;
            }
            if !oracle_gen(&js_dir.join(format!("{}.par2", base)), &args, &[&a, &b]) {
                eprintln!("e2e_gen: no oracle available (node+addon or FFI bin) - skipping");
                return;
            }
        }
    }

    let names: Vec<String> = ["a.bin", "b.bin"]
        .iter()
        .map(|n| in_dir.join(n).to_string_lossy().into_owned())
        .collect();
    let mut files =
        parpar::fileinfo::file_info(&names, parpar::args::Recurse::No, false, 0, None).unwrap();

    run_case(
        &mut files,
        &js_dir,
        &dir,
        "out",
        SpecTerm {
            unit: SpecUnit::Bytes,
            value: 512.0,
            scale: 1.0,
        },
        |o| {
            o.recovery_slices = vec![SpecTerm {
                unit: SpecUnit::Slices,
                value: 3.0,
                scale: 1.0,
            }];
        },
        3,
    );

    // chunked path: 64K slices, 64K memory limit, 1K min chunk ->
    // 6 passes of 3 x ~10.7K chunks (JS oracle: outc.*)
    run_case(
        &mut files,
        &js_dir,
        &dir,
        "outc",
        SpecTerm {
            unit: SpecUnit::Bytes,
            value: 65536.0,
            scale: 1.0,
        },
        |o| {
            o.recovery_slices = vec![SpecTerm {
                unit: SpecUnit::Slices,
                value: 3.0,
                scale: 1.0,
            }];
            o.memory_limit = Some(65536.0);
            o.min_chunk_size = 1024.0;
        },
        3,
    );

    // larger multi-slice inputs (JS oracle: big.* / mp.*)
    let in2 = js_dir.join("in2");
    {
        if !in2.join("big.bin").exists() {
            std::fs::create_dir_all(&in2).unwrap();
            let mut rng = 0x2au32;
            let mut next = move || {
                rng = rng.wrapping_mul(1664525).wrapping_add(1013904223);
                (rng >> 16) as u8
            };
            std::fs::write(
                in2.join("big.bin"),
                (0..400 * 1024).map(|_| next()).collect::<Vec<u8>>(),
            )
            .unwrap();
            std::fs::write(
                in2.join("med.bin"),
                (0..150 * 1024)
                    .map(|i| (i * 7 & 0xff) as u8)
                    .collect::<Vec<u8>>(),
            )
            .unwrap();
        }
        for (base, args) in [
            (
                "big",
                vec!["-s64K", "-r5", "-m128K", "--min-chunk-size", "4K"],
            ),
            (
                "mp",
                vec!["-s256K", "-r10", "-m1600K", "--min-chunk-size", "64K"],
            ),
        ] {
            if js_dir.join(format!("{}.par2", base)).exists() {
                continue;
            }
            let big = in2.join("big.bin");
            let med = in2.join("med.bin");
            if !oracle_gen(&js_dir.join(format!("{}.par2", base)), &args, &[&big, &med]) {
                eprintln!("e2e_gen: no oracle available - skipping");
                return;
            }
        }
    }
    let names2: Vec<String> = ["big.bin", "med.bin"]
        .iter()
        .map(|n| in2.join(n).to_string_lossy().into_owned())
        .collect();
    let mut files2 =
        parpar::fileinfo::file_info(&names2, parpar::args::Recurse::No, false, 0, None).unwrap();

    // multi-slice chunked: 9 slices x 5 chunks, 5 recovery (oracle big.*)
    run_case(
        &mut files2,
        &js_dir,
        &dir,
        "big",
        SpecTerm {
            unit: SpecUnit::Bytes,
            value: 65536.0,
            scale: 1.0,
        },
        |o| {
            o.recovery_slices = vec![SpecTerm {
                unit: SpecUnit::Slices,
                value: 5.0,
                scale: 1.0,
            }];
            o.memory_limit = Some(131072.0);
            o.min_chunk_size = 4096.0;
        },
        4,
    );

    // same chunked case through the native parpar-hasher path - output must
    // be byte-identical to the FFI run (and therefore to the JS oracle)
    run_case(
        &mut files2,
        &js_dir,
        &dir,
        "big",
        SpecTerm {
            unit: SpecUnit::Bytes,
            value: 65536.0,
            scale: 1.0,
        },
        |o| {
            o.recovery_slices = vec![SpecTerm {
                unit: SpecUnit::Slices,
                value: 5.0,
                scale: 1.0,
            }];
            o.memory_limit = Some(131072.0);
            o.min_chunk_size = 4096.0;
        },
        4,
    );

    // the same chunked case through the native parpar-gf16 scalar CPU
    // processor - recovery data must be byte-identical to the FFI/JS oracle
    run_case(
        &mut files2,
        &js_dir,
        &dir,
        "big",
        SpecTerm {
            unit: SpecUnit::Bytes,
            value: 65536.0,
            scale: 1.0,
        },
        |o| {
            o.recovery_slices = vec![SpecTerm {
                unit: SpecUnit::Slices,
                value: 5.0,
                scale: 1.0,
            }];
            o.memory_limit = Some(131072.0);
            o.min_chunk_size = 4096.0;
        },
        4,
    );

    // multi recovery-pass chunked: 4 slices, 10 rec slices over batches
    // (oracle mp.*)
    run_case(
        &mut files2,
        &js_dir,
        &dir,
        "mp",
        SpecTerm {
            unit: SpecUnit::Bytes,
            value: 262144.0,
            scale: 1.0,
        },
        |o| {
            o.recovery_slices = vec![SpecTerm {
                unit: SpecUnit::Slices,
                value: 10.0,
                scale: 1.0,
            }];
            o.memory_limit = Some(1638400.0);
            o.min_chunk_size = 65536.0;
        },
        5,
    );
}

#[allow(clippy::too_many_arguments)]
fn run_case(
    files: &mut Vec<parpar::fileinfo::FileInfo>,
    js_dir: &std::path::Path,
    dir: &std::path::Path,
    base: &str,
    slice_def: SpecTerm,
    mut configure: impl FnMut(&mut GenOpts),
    expected_vols: usize,
) {
    let out_base = dir.join(base).to_string_lossy().into_owned();
    let mut o = GenOpts::default();
    o.gf_method = Some(MethodRef::Name("".into()));
    o.output_base = out_base;
    o.output_overwrite = true;
    o.creator = "ParPar v0.5.3 x64 [https://github.com/animetosho/parpar]".into();
    configure(&mut o);

    let env = SysEnv {
        total_mem: u64::MAX,
        free_mem: u64::MAX,
        constrained_mem: u64::MAX,
        is_64b: true,
        k_max_length: u64::MAX,
    };
    let mut shared = SharedBackend::new(NativeBackend::new());
    shared.set_native_hashers(true);
    shared.set_native_proc(true);
    let mut gen = Par2Gen::new(
        files,
        &slice_def,
        o,
        shared.clone(),
        "utf-8",
        &mut shared,
        &env,
    )
    .unwrap();

    let mut drv = GenDriver::new(&mut gen).unwrap();
    drv.run(&mut |_| {}).unwrap();

    let mut compared = 0;
    for rf in &drv.out_files {
        let produced = std::fs::read(&rf.name).unwrap();
        let oracle_name = js_dir.join(
            std::path::Path::new(&rf.name)
                .file_name()
                .unwrap()
                .to_string_lossy()
                .into_owned(),
        );
        let oracle = std::fs::read(&oracle_name).unwrap();
        assert_eq!(
            produced.len(),
            oracle.len(),
            "size mismatch for {}",
            rf.name
        );
        assert_eq!(produced, oracle, "content mismatch for {}", rf.name);
        compared += 1;
    }
    assert_eq!(compared, expected_vols, "volume count for {}", base);
    assert_eq!(drv.slice_offset as f64, gen.opts.recovery_slices_res);
}
